import numpy as np
from scipy.interpolate import RBFInterpolator
from scipy.optimize import brentq

_X = np.array([[0.8, -0.55, 0.0], [0.15, -0.12, 0.045], [0.15, -0.12, 0.0], [0.4, -0.12, 0.045], [0.7, -0.12, 0.045], [0.4, -0.3, 0.045], [0.4, -0.12, -0.045], [0.15, -0.3, 0.045], [0.7, -0.12, -0.045], [0.9904761203564704, -0.346361146569252, 0.03755436572246253], [0.15, -1.0, -0.045], [0.15, -1.0, 0.045], [1.4, -1.0, -0.045], [1.4, -1.0, 0.045], [1.4, -0.12, -0.045], [1.4, -0.12, 0.045], [0.15, -0.55, -0.045], [0.15, -0.55, 0.045], [1.4, -0.55, 0.0], [0.22960278657265007, -0.9856520773470402, -0.012272848002612594], [0.775, -1.0, 0.0], [0.775, -0.12, 0.0], [0.5100994414915824, -0.4381455612971671, 0.03233221058044891], [0.4093924657577801, -0.9424541628814246, -0.006925598240120845], [1.3388974707475492, -0.25958051050087905, -0.03614416466550532], [0.9464508934920596, -0.7892808811246462, -0.033448103901884164], [0.7694008981783319, -0.5014818874428214, -0.039195462845204886], [1.2719493691649864, -0.3752594287165093, -0.005486806352642391], [0.917748386170426, -0.30602556346084886, 0.01898377799009976], [0.6845655011478812, -0.2565349012613296, 0.018617919031530622], [0.4541482036417239, -0.7956173109680995, -0.03559444296589897], [0.1654617647733574, -0.17596113035229288, -0.011215910832655787], [0.6617229939156212, -0.38885158350403426, 0.01060384310379986], [0.2109298564001572, -0.3222378700759929, 0.010005643847746173], [1.083824501967372, -0.678500693888542, 0.004857132729655052], [0.7796163612148296, -0.42590339014570244, -0.013019633799622364], [1.210941168575172, -0.8774282677005819, 0.019804842622223803], [0.80957786527278, -0.993703566527532, -0.029916754044673453], [0.5836308439036929, -0.19945720082871687, -0.04352977226107432], [1.170946332719177, -0.6620895744860172, -0.04387899848632514], [0.8858636263234506, -0.47490538583154696, 0.03092700010722363], [1.2459583028750167, -0.741072277653228, 0.003534871080500823], [1.298629940063183, -0.8200547169904175, -0.004343793349596649], [1.1557635228854557, -0.40463398448580445, -0.01611863201214046], [0.2736853419365878, -0.5525770360252329, -0.019700941876484628], [0.6879026336715574, -0.23705213760785415, -0.017572557885958164], [0.4298081238597473, -0.9140953321734697, 0.03843401945310326], [1.330506208789246, -0.7050400213808139, -0.02248611305361863], [1.0939792115274287, -0.3345512589404168, 0.00814200408888767], [1.397624127427116, -0.21727711431682106, -0.008458079919219014], [0.2475651757274981, -0.6377404614136832, -0.00887956247105054], [0.6380990484842923, -0.6756779608391656, -0.014994023750135706], [1.0393145228771028, -0.46380949956329265, 0.03930897300088036], [0.3725071509997979, -0.627280149982891, 0.02270628614444478], [0.47362554719865424, -0.9736797595368524, 0.017105903028634885], [0.8578899577880044, -0.904349814666317, -0.023092077735883017], [1.3918769802348536, -0.8869595650011866, -0.042648382698214124], [1.0132029333074268, -0.9632723724355496, 0.04081973962970052], [0.6916791944439573, -0.3529722368914475, 0.04230616212529903], [0.48171077026054265, -0.6915749195963145, 0.028197000464424485], [0.5585397675028199, -0.2830204696841311, -0.0018216631571992409], [1.289785059840891, -0.6499498920659538, 0.04424021501936777]], dtype=float)
_Y = np.array([-3.96997, -0.6377, -0.72552, -0.96783, -1.4653, -1.36711, -1.27179, -0.87795, -1.97032, -2.9661, -1.79009, -1.494, -6.33735, -4.49465, -2.60622, -1.76842, -1.36255, -1.17559, -3.98506, -2.16919, -5.6166, -1.90752, -2.11053, -2.99342, -3.43314, -6.25697, -4.0979, -3.76237, -2.93348, -2.17197, -3.10597, -0.8772, -2.67334, -1.14532, -5.15858, -3.49791, -5.52693, -6.628, -1.98906, -5.93323, -3.40781, -5.25296, -5.55203, -4.23912, -1.80128, -2.33468, -2.65838, -5.2312, -3.49438, -2.73969, -1.7341, -3.69565, -3.5383, -2.02241, -3.16711, -6.20731, -5.65126, -5.41963, -2.30667, -2.58319, -2.04429, -3.8922], dtype=float)
_LO = np.array([0.15, -1.0, -0.045])
_SCALE = np.array([1.25, 0.88, 0.09])
_Z = (_X - _LO) / _SCALE

# An ensemble of two smooth interpolants. Cross-validation errors on the 62
# measurements were about 0.07 m (Gaussian) and 0.09 m (multiquadric).
_G = RBFInterpolator(_Z, _Y, kernel="gaussian", epsilon=0.7, smoothing=1e-5)
_M = RBFInterpolator(_Z, _Y, kernel="multiquadric", epsilon=0.7, smoothing=5e-6)

def _landing(theta, speed):
    x0 = 0.2 * np.sin(theta)
    z0 = 0.62 + 0.2 * np.cos(theta)
    vx = -speed * np.cos(theta)
    vz = speed * np.sin(theta)
    tf = (vz + np.sqrt(vz*vz + 2.0*9.81*(z0 - 0.016))) / 9.81
    return x0 + vx * tf

def predict(knobs: dict, visible: dict) -> list[float]:
    c = float(knobs["cock"])
    p = float(knobs["power"])
    s = float(knobs["shift"])
    z = (np.array([c, p, s]) - _LO) / _SCALE
    base = float(0.72*_G(z[None, :])[0] + 0.28*_M(z[None, :])[0])

    # At the reference dimensions the ball normally separates just before the
    # striker reaches the post. A moved-in post can pre-empt that separation in
    # the low-energy corner. The contact angle follows directly from the box
    # support geometry: (radial offset + half-height)*sin(q)-half-width*cos(q).
    postx = float(visible.get("stop_post.posx", -0.04))
    strikerz = float(visible.get("striker.posz", 0.71))
    a = strikerz - 0.62 + 0.014
    rhs = postx + 0.020
    ratio = np.clip(rhs / np.hypot(a, 0.008), -1.0, 1.0)
    stop_angle = np.arctan2(0.008, a) + np.arcsin(ratio)
    stop_angle = max(stop_angle, -0.600)

    dc = max(c - 0.15, 0.0)
    dp = max(abs(p) - 0.12, 0.0)
    natural_angle = (-0.087 + 0.50*(1.0-np.exp(-dc/0.35))
                     + 0.90*dp - 0.62*(s-0.045))
    natural_angle = min(natural_angle, c - 0.01)
    if stop_angle > natural_angle:
        # Infer the reference tangential speed from its landing range, then
        # scale kinetic energy by the shorter angular travel to the new stop.
        try:
            speed = brentq(lambda v: _landing(natural_angle, v)-base, 0.05, 30.0)
            den = max(c - natural_angle, 0.01)
            speed *= np.sqrt(max(c - stop_angle, 0.002) / den)
            base = _landing(stop_angle, speed)
        except ValueError:
            pass
    return [float(base)]
